test('roster display order is reshuffled at start(), breaking the lobby -> game position mapping',()=>{
  // Codenames are handed out in seat order, so a seat-ordered in-game roster
  // used to keep every player on the row they occupied in the lobby — which
  // handed anyone who glanced at the lobby a complete codename -> real-name
  // mapping and defeated anonymized mode outright. It also gave whoever
  // joined first a permanent top-of-list position in a game whose core act is
  // voting on that list. start() now assigns a fresh random display_order.
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-order-'));
  // random:()=>0 makes every Fisher-Yates draw pick index 0, giving the
  // deterministic rotation [1,2,3,4,0]. (A constant 0.9 would instead make
  // every swap a self-swap and leave the order untouched.)
  const manager=new HeresyGameManager({databasePath:path.join(dir,'game.db'),now:()=>1_000_000,random:()=>0});
  try{
    const {code}=manager.create({playerCode:'p0',name:'P0'});
    for(let i=1;i<5;i++){manager.join({code,playerCode:`p${i}`,name:`P${i}`});manager.ready(code,`p${i}`,true);}
    const lobbyOrder=manager.state(code,'p1').players.map(p=>p.playerCode);
    assert.deepEqual(lobbyOrder,['p0','p1','p2','p3','p4'],'lobby stays in join/seat order');

    manager.start(code,'p0');
    const gameOrder=manager.state(code,'p1').players.map(p=>p.playerCode);
    assert.notDeepEqual(gameOrder,lobbyOrder,'in-game roster is not the lobby order');
    assert.deepEqual([...gameOrder].sort(),[...lobbyOrder].sort(),'same players, only reordered');

    // Every viewer sees the one shared order, and it is stable across reads
    // (persisted, not recomputed per request — otherwise the roster would
    // reshuffle under players on every state push).
    assert.deepEqual(manager.state(code,'p3').players.map(p=>p.playerCode),gameOrder,'same order for every viewer');
    assert.deepEqual(manager.state(code,'p1').players.map(p=>p.playerCode),gameOrder,'stable across repeated reads');
    assert.deepEqual(manager.spectate(code).players.map(p=>p.playerCode),gameOrder,'spectators see it too');

    // players() stays seat-ordered — game logic (role dealing, codename
    // assignment) is indexed by it and must not follow the display shuffle.
    assert.deepEqual(manager.players(code).map(p=>p.player_code),['p0','p1','p2','p3','p4']);
  }finally{manager.close();fs.rmSync(dir,{recursive:true,force:true});}
});

test('roster shuffle applies in non-anonymized games too, and survives a manager restart',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-order2-'));
  const dbPath=path.join(dir,'game.db');
  let order;
  const manager=new HeresyGameManager({databasePath:dbPath,now:()=>1_000_000,random:()=>0});
  try{
    const {code}=manager.create({playerCode:'p0',name:'P0'}); // anonymized OFF
    for(let i=1;i<5;i++){manager.join({code,playerCode:`p${i}`,name:`P${i}`});manager.ready(code,`p${i}`,true);}
    manager.start(code,'p0');
    assert.equal(manager.game(code).anonymized,0,'this game is not anonymized');
    order=manager.state(code,'p1').players.map(p=>p.playerCode);
    assert.notDeepEqual(order,['p0','p1','p2','p3','p4'],'shuffled even without anonymized mode');
    manager.close();

    // Reopening the DB must yield the same roster — the order is a stored
    // column, so a server restart mid-game doesn't rearrange the table.
    const reopened=new HeresyGameManager({databasePath:dbPath,now:()=>1_000_000,random:()=>0});
    try{ assert.deepEqual(reopened.state(code,'p1').players.map(p=>p.playerCode),order,'order persists across restart'); }
    finally{ reopened.close(); }
  }finally{fs.rmSync(dir,{recursive:true,force:true});}
});

test('player prefs: persist across devices by playerCode, independent of any game',()=>{
  const f=fixture();
  try{
    // No game context at all — this is a global, per-identity store.
    const empty=f.manager.getPlayerPrefs('HR-SOMEONE');
    assert.deepEqual(empty,{},'unknown playerCode returns an empty object, not an error');

    const saved=f.manager.setPlayerPrefs('HR-SOMEONE',{sealStyle:'coloured-mono'});
    assert.deepEqual(saved,{sealStyle:'coloured-mono'});
    assert.deepEqual(f.manager.getPlayerPrefs('HR-SOMEONE'),{sealStyle:'coloured-mono'},'a second read (simulating a second device) sees the same value');

    // Setting again merges rather than replacing — future preference keys
    // shouldn't clobber each other.
    f.manager.setPlayerPrefs('HR-SOMEONE',{otherThing:'x'});
    assert.deepEqual(f.manager.getPlayerPrefs('HR-SOMEONE'),{sealStyle:'coloured-mono',otherThing:'x'});

    // A different playerCode is fully isolated.
    assert.deepEqual(f.manager.getPlayerPrefs('HR-DIFFERENT'),{});
  }finally{f.close();}
});

test('player prefs: garbage input is rejected or dropped, never corrupts the store',()=>{
  const f=fixture();
  try{
    assert.throws(()=>f.manager.setPlayerPrefs('HR-X',null),/Invalid preferences payload/);
    assert.throws(()=>f.manager.setPlayerPrefs('HR-X',['not','an','object']),/Invalid preferences payload/);
    assert.throws(()=>f.manager.setPlayerPrefs('HR-X','a string'),/Invalid preferences payload/);

    // Non-primitive values are silently dropped rather than stored or thrown on.
    const result=f.manager.setPlayerPrefs('HR-X',{sealStyle:'ordinary',nested:{a:1},arr:[1,2]});
    assert.deepEqual(result,{sealStyle:'ordinary'});

    // An oversized payload is rejected outright rather than truncated.
    const huge={};
    for(let i=0;i<50;i++)huge['k'+i]='v'.repeat(200);
    assert.throws(()=>f.manager.setPlayerPrefs('HR-Y',huge),/too large/);
  }finally{f.close();}
});

test('listPlayerGames: lists every conclave a playerCode has a seat in, active games always sorted before ended ones',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-switcher-'));
  let now=1_000_000;
  const manager=new HeresyGameManager({databasePath:path.join(dir,'game.db'),now:()=>now,random:()=>0.9});
  try{
    // Game A: lobby, this player is host.
    const {code:codeA}=manager.create({playerCode:'p0',name:'Host'});
    // Game B: started (active), joined as a non-host.
    const {code:codeB}=manager.create({playerCode:'other',name:'OtherHost'});
    manager.join({code:codeB,playerCode:'p0',name:'P0'});
    for(let i=1;i<5;i++){manager.join({code:codeB,playerCode:`b${i}`,name:`B${i}`});manager.ready(codeB,`b${i}`,true);}
    manager.ready(codeB,'other',true);manager.ready(codeB,'p0',true);
    now+=1000;
    manager.start(codeB,'other');
    // Game C: ended a long time ago (outside the default 24h window) — must not appear.
    const {code:codeC}=manager.create({playerCode:'p0',name:'Host2'});
    manager.db.prepare("UPDATE hr_games SET status='ended',updated_at=? WHERE code=?").run(now-25*60*60*1000,codeC);
    // Game D: ended recently (within the window) — must appear, but after A/B.
    const {code:codeD}=manager.create({playerCode:'p0',name:'Host3'});
    now+=1000;
    manager.db.prepare("UPDATE hr_games SET status='ended',winner='loyalist',updated_at=? WHERE code=?").run(now,codeD);
    // Game E: this player was never in it — must not appear regardless of status.
    manager.create({playerCode:'stranger',name:'Stranger'});

    const list=manager.listPlayerGames('p0');
    const codes=list.map(g=>g.code);
    assert.ok(codes.includes(codeA)&&codes.includes(codeB)&&codes.includes(codeD),'A, B and D all present');
    assert.ok(!codes.includes(codeC),'C is outside the 24h window and must not appear');
    const endedIndex=codes.indexOf(codeD),lastActiveIndex=Math.max(codes.indexOf(codeA),codes.indexOf(codeB));
    assert.ok(lastActiveIndex<endedIndex,'every non-ended game sorts before the ended one, regardless of recency');

    const entryA=list.find(g=>g.code===codeA);
    assert.equal(entryA.status,'lobby');assert.equal(entryA.isHost,true);assert.equal(entryA.playerCount,1);

    const entryB=list.find(g=>g.code===codeB);
    assert.equal(entryB.status,'active');assert.equal(entryB.phase,'day');assert.equal(entryB.isHost,false,'joined, not hosted');assert.equal(entryB.playerCount,6);

    const entryD=list.find(g=>g.code===codeD);
    assert.equal(entryD.status,'ended');assert.equal(entryD.winner,'loyalist');

    assert.deepEqual(manager.listPlayerGames('ghost-code'),[],'a playerCode with no games at all returns an empty list, not an error');
  }finally{manager.close();fs.rmSync(dir,{recursive:true,force:true});}
});

test('game:leave — a solo lobby is disbanded outright, not left as an orphaned shell',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-leave-'));
  const manager=new HeresyGameManager({databasePath:path.join(dir,'game.db')});
  try{
    const {code}=manager.create({playerCode:'p0',name:'Solo'});
    assert.ok(manager.game(code),'game exists before leaving');

    const result=manager.leave(code,'p0');
    assert.deepEqual(result,{disbanded:true});
    assert.equal(manager.game(code),undefined,'the game row itself is gone');
    assert.deepEqual(manager.players(code),[],'no player rows survive either');

    // Fully gone, not just emptied — a second leave call on the same
    // (now nonexistent) code must fail cleanly rather than resurrect anything.
    assert.throws(()=>manager.leave(code,'p0'));
  }finally{manager.close();fs.rmSync(dir,{recursive:true,force:true});}
});

test('game:leave — leaving a lobby with other players present only disconnects, never disbands',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-leave2-'));
  const manager=new HeresyGameManager({databasePath:path.join(dir,'game.db')});
  try{
    const {code}=manager.create({playerCode:'p0',name:'Host'});
    manager.join({code,playerCode:'p1',name:'P1'});

    const result=manager.leave(code,'p0');
    assert.deepEqual(result,{disbanded:false});
    assert.ok(manager.game(code),'game still exists — another player remains');
    assert.equal(manager.player(code,'p0').connected,0,'the leaver is marked disconnected, not removed — this is what lets them return with the same code');
    assert.ok(manager.player(code,'p1'),'the remaining player is untouched');

    // p1 leaving too does NOT cascade into a disband, even though p0's row
    // is now disconnected: "alone" is judged by row presence, not live
    // connection state. The alternative (count only currently-connected
    // rows) would mean one player's explicit leave could disband a lobby
    // out from under someone else who is merely mid-reconnect after a
    // network blip — worse than the gap it would close. p0's disconnected
    // seat still means "someone else has a stake in this lobby."
    const secondResult=manager.leave(code,'p1');
    assert.deepEqual(secondResult,{disbanded:false},"p0's disconnected-but-present row keeps this from counting as empty");
    assert.ok(manager.game(code),'game still exists — both rows are disconnected but neither was ever removed');
  }finally{manager.close();fs.rmSync(dir,{recursive:true,force:true});}
});

test('game:leave — never disbands a started game, even if the leaver was the last one connected',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-leave3-'));
  const manager=new HeresyGameManager({databasePath:path.join(dir,'game.db')});
  try{
    const {code}=manager.create({playerCode:'p0',name:'Host'});
    for(let i=1;i<5;i++){manager.join({code,playerCode:`p${i}`,name:`P${i}`});manager.ready(code,`p${i}`,true);}
    manager.ready(code,'p0',true);
    manager.start(code,'p0');

    const result=manager.leave(code,'p0');
    assert.deepEqual(result,{disbanded:false},'started games are never disbanded by a leave, regardless of headcount');
    assert.ok(manager.game(code),'the game record survives');
    assert.equal(manager.player(code,'p0').connected,0);
  }finally{manager.close();fs.rmSync(dir,{recursive:true,force:true});}
});

test('game:leave — a bot left alone in the lobby after the host leaves is NOT enough to disband (only a true zero-player lobby is)',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-leave4-'));
  const manager=new HeresyGameManager({databasePath:path.join(dir,'game.db')});
  try{
    const {code}=manager.create({playerCode:'p0',name:'Host'});
    manager.adminSpawnBot(code,{name:'Bot One'});

    const result=manager.leave(code,'p0');
    assert.deepEqual(result,{disbanded:false},'a bot is still a row in the lobby, so the host leaving does not zero it out');
    assert.ok(manager.game(code));
  }finally{manager.close();fs.rmSync(dir,{recursive:true,force:true});}
});

// A voter can update the reasoning behind a vote they already cast: re-casting
// the SAME choice posts the new justification without disturbing the tally or
// re-announcing the accusation.
test('re-casting the same vote with a justification posts it without re-announcing the accusation',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.player_code!=='p0');f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);
  const first=f.manager.vote(f.code,'p0',target.player_code,'he lied about the crypt');assert.match(first.message.body,/he lied about the crypt/);
  const second=f.manager.vote(f.code,'p0',target.player_code,'and his alibi does not hold');assert.match(second.message.body,/his alibi does not hold/,'the updated justification is posted');
  assert.equal(f.manager.voteState(f.code).filter(v=>v.voterCode==='p0').length,1,'still exactly one vote on record');
  assert.equal(f.manager.voteState(f.code).find(v=>v.voterCode==='p0').choice,target.player_code,'and it still points at the same target');
  const bodies=f.manager.historyMessages(f.code,'p0','public').messages.map(m=>m.body);
  assert.equal(bodies.filter(b=>/accused/.test(b)).length,1,'the accusation is announced once, not once per justification');
  assert.equal(f.manager.vote(f.code,'p0',target.player_code).message,null,'a bare re-cast with no justification stays a silent no-op');
}finally{f.close();}});
